// InitiateFederatedLogin implements mm_port.FederatedLoginUseCase
func (mmInitiateFederatedLogin *FederatedLoginUseCaseMock) InitiateFederatedLogin(ctx context.Context, cmd mm_port.InitiateFederatedLoginCommand) (ip1 *mm_port.InitiateFederatedLoginResponse, err error) {
	mm_atomic.AddUint64(&mmInitiateFederatedLogin.beforeInitiateFederatedLoginCounter, 1)
	defer mm_atomic.AddUint64(&mmInitiateFederatedLogin.afterInitiateFederatedLoginCounter, 1)

	mmInitiateFederatedLogin.t.Helper()

	if mmInitiateFederatedLogin.inspectFuncInitiateFederatedLogin != nil {
		mmInitiateFederatedLogin.inspectFuncInitiateFederatedLogin(ctx, cmd)
	}

	mm_params := FederatedLoginUseCaseMockInitiateFederatedLoginParams{ctx, cmd}

	// Record call args
	mmInitiateFederatedLogin.InitiateFederatedLoginMock.mutex.Lock()
	mmInitiateFederatedLogin.InitiateFederatedLoginMock.callArgs = append(mmInitiateFederatedLogin.InitiateFederatedLoginMock.callArgs, &mm_params)
	mmInitiateFederatedLogin.InitiateFederatedLoginMock.mutex.Unlock()

	for _, e := range mmInitiateFederatedLogin.InitiateFederatedLoginMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.ip1, e.results.err
		}
	}

	if mmInitiateFederatedLogin.InitiateFederatedLoginMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmInitiateFederatedLogin.InitiateFederatedLoginMock.defaultExpectation.Counter, 1)
		mm_want := mmInitiateFederatedLogin.InitiateFederatedLoginMock.defaultExpectation.params
		mm_want_ptrs := mmInitiateFederatedLogin.InitiateFederatedLoginMock.defaultExpectation.paramPtrs

		mm_got := FederatedLoginUseCaseMockInitiateFederatedLoginParams{ctx, cmd}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmInitiateFederatedLogin.t.Errorf("FederatedLoginUseCaseMock.InitiateFederatedLogin got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmInitiateFederatedLogin.InitiateFederatedLoginMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.cmd != nil && !minimock.Equal(*mm_want_ptrs.cmd, mm_got.cmd) {
				mmInitiateFederatedLogin.t.Errorf("FederatedLoginUseCaseMock.InitiateFederatedLogin got unexpected parameter cmd, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmInitiateFederatedLogin.InitiateFederatedLoginMock.defaultExpectation.expectationOrigins.originCmd, *mm_want_ptrs.cmd, mm_got.cmd, minimock.Diff(*mm_want_ptrs.cmd, mm_got.cmd))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmInitiateFederatedLogin.t.Errorf("FederatedLoginUseCaseMock.InitiateFederatedLogin got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmInitiateFederatedLogin.InitiateFederatedLoginMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmInitiateFederatedLogin.InitiateFederatedLoginMock.defaultExpectation.results
		if mm_results == nil {
			mmInitiateFederatedLogin.t.Fatal("No results are set for the FederatedLoginUseCaseMock.InitiateFederatedLogin")
		}
		return (*mm_results).ip1, (*mm_results).err
	}
	if mmInitiateFederatedLogin.funcInitiateFederatedLogin != nil {
		return mmInitiateFederatedLogin.funcInitiateFederatedLogin(ctx, cmd)
	}
	mmInitiateFederatedLogin.t.Fatalf("Unexpected call to FederatedLoginUseCaseMock.InitiateFederatedLogin. %v %v", ctx, cmd)
	return
}

