// MinimockInitiateFederatedLoginDone returns true if the count of the InitiateFederatedLogin invocations corresponds
// the number of defined expectations
func (m *FederatedLoginUseCaseMock) MinimockInitiateFederatedLoginDone() bool {
	if m.InitiateFederatedLoginMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.InitiateFederatedLoginMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.InitiateFederatedLoginMock.invocationsDone()
}

// MinimockInitiateFederatedLoginInspect logs each unmet expectation
func (m *FederatedLoginUseCaseMock) MinimockInitiateFederatedLoginInspect() {
	for _, e := range m.InitiateFederatedLoginMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to FederatedLoginUseCaseMock.InitiateFederatedLogin at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterInitiateFederatedLoginCounter := mm_atomic.LoadUint64(&m.afterInitiateFederatedLoginCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.InitiateFederatedLoginMock.defaultExpectation != nil && afterInitiateFederatedLoginCounter < 1 {
		if m.InitiateFederatedLoginMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to FederatedLoginUseCaseMock.InitiateFederatedLogin at\n%s", m.InitiateFederatedLoginMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to FederatedLoginUseCaseMock.InitiateFederatedLogin at\n%s with params: %#v", m.InitiateFederatedLoginMock.defaultExpectation.expectationOrigins.origin, *m.InitiateFederatedLoginMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcInitiateFederatedLogin != nil && afterInitiateFederatedLoginCounter < 1 {
		m.t.Errorf("Expected call to FederatedLoginUseCaseMock.InitiateFederatedLogin at\n%s", m.funcInitiateFederatedLoginOrigin)
	}

	if !m.InitiateFederatedLoginMock.invocationsDone() && afterInitiateFederatedLoginCounter > 0 {
		m.t.Errorf("Expected %d calls to FederatedLoginUseCaseMock.InitiateFederatedLogin at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.InitiateFederatedLoginMock.expectedInvocations), m.InitiateFederatedLoginMock.expectedInvocationsOrigin, afterInitiateFederatedLoginCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *FederatedLoginUseCaseMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockExecuteFederatedCallbackInspect()

			m.MinimockInitiateFederatedLoginInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *FederatedLoginUseCaseMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *FederatedLoginUseCaseMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockExecuteFederatedCallbackDone() &&
		m.MinimockInitiateFederatedLoginDone()
}
